from lib import *
S = SS('f142')
R = J('f142'); ge = R['gevent']; cm = R['cmp']; cb = R['cpu_block']; cg = R['cpu_block_gthread']
gt = cm['gthread 1×8 线程']; sy = cm['sync 1 个 worker(只测 8 个)']
steps = [
    step(f"gunicorn 的 gevent worker:1 个进程同时处理 100 个各睡 1 秒的请求,总耗时 {ge[0] / 1000:.2f} 秒(睡眠被 gevent 的 monkey patch 变成了协作式的让出)。进程数 {ge[1]};threading.get_ident() 有 {ge[2]} 个不同的值——每个请求是一个 greenlet,patch 之后线程标识就是 greenlet 的标识;每个请求把参数写进 g、睡 1 秒再读回,读成别人的值的有 {ge[3]} 个。Flask 的 request、g 在 greenlet 之间没有串。", b=bars([['gevent 1 进程', ge[0] / 1000, f'{ge[0] / 1000:.2f} s']], 14, done=[0]), t=tl(S(1)), done=lidx(S(1), '100 个并发请求'), kv=KV([['100 个请求', f'{ge[0] / 1000:.2f} 秒,1 个进程'], ['g 串了吗', f'{ge[3]} 个']], ['100 个请求'])),
    step(f"对比:gthread 1 个 worker × 8 线程处理同样的 100 个各睡 1 秒的请求要 {gt[1] / 1000:.2f} 秒(8 个线程一批一批地处理);sync 1 个 worker 处理 8 个就要 {sy[1] / 1000:.2f} 秒。等待型的请求,greenlet 的并发度由连接数决定,线程的并发度由线程数决定。", b=bars([['gevent 100 个', ge[0] / 1000, f'{ge[0] / 1000:.1f} s'], ['gthread 8 线程 100 个', gt[1] / 1000, f'{gt[1] / 1000:.1f} s'], ['sync 1 worker 8 个', sy[1] / 1000, f'{sy[1] / 1000:.1f} s']], gt[1] / 1000, done=[0], mark=[1, 2]), t=tl(S(2)), done=lidx(S(2), 'gthread'), mark=lidx(S(2), 'sync'), kv=KV([['gthread 8 线程 × 100 个', f'{gt[1] / 1000:.1f} 秒'], ['gevent × 100 个', f'{ge[0] / 1000:.1f} 秒']], ['gevent × 100 个'])),
    step(f"greenlet 是协作式的:一个约 0.8 秒的纯计算请求进行中,/fast 请求在 gevent worker 里用了 {cb:.0f} ms(要等计算那一段结束,没有抢占),gthread 里同样的场景是 {cg:.0f} ms(线程由解释器轮流调度)。gevent 适合 I/O 等待多、计算少的服务;计算多的请求要交给别的进程。(这个 {cb:.0f} ms 是在计算开始后 0.2 秒才发出 /fast 的剩余等待时间,不是整个计算时长。)", t=tl(S(3)), mark=lidx(S(3), '一个约 0.8 秒'), done=lidx(S(3), 'gthread'), kv=KV([['gevent', f'计算期间其它请求等 {cb:.0f} ms'], ['gthread', f'{cg:.0f} ms']], ['gevent'])),
    step("threading.local 与 greenlet:没有 monkey patch 时,三个 greenlet 各自往 threading.local 写入 A、B、C,睡 0.1 秒再读回,三个读到的都是 C(同一个线程里共享了同一个 local);patch_all 之后新建的 threading.local 变成按 greenlet 隔离,读回 A、B、C;contextvars 不需要 patch 就是按 greenlet 隔离的(读回 A、B、C)。Werkzeug 的 Local 基于 contextvars,所以 Flask 的 request 与 g 在 greenlet 里是安全的;但是用 threading.local 保存请求状态的第三方库,必须在 gevent 之前先 patch。", t=tl(S(4)), mark=lidx(S(4), '未 patch'), done=lidx(S(4), 'patch_all 之后', 'contextvars'), kv=KV([['未 patch 的 threading.local', 'greenlet 之间共享,会串'], ['contextvars', '天然按 greenlet 隔离']], ['未 patch 的 threading.local'])),
]
A = mkartf('f142', 142, 'Flask,gevent,greenlet,上下文,真实验证,动画演示',
    f'实测 Greenlet 与 Flask 上下文:gunicorn 的 gevent worker 用 1 个进程处理 100 个各睡 1 秒的请求只要 {ge[0] / 1000:.2f} 秒且 g 没有串(gthread 8 线程要 {gt[1] / 1000:.1f} 秒);协作式调度下纯计算请求会卡住其它请求;未 patch 的 threading.local 在 greenlet 之间共享而 contextvars 不会。',
    'gevent 为什么能让 Flask 同时处理上百个等待中的请求?request 与 g 会不会在 greenlet 之间串?纯计算的请求会怎样?threading.local 要不要 patch?这篇用真实的 gunicorn gevent worker 把这些量出来。',
    [(f'{ge[0] / 1000:.2f} 秒', 'gevent 单进程处理 100 个各睡 1 秒的请求的总耗时'), (f'{ge[3]} 个', '100 个并发请求里 g 读到别人的值的个数'), ('C, C, C', '未 patch 的 threading.local 在三个 greenlet 里读回的值')],
    [('gevent 并发等待请求', '<p>上一篇:<a href="flask-wsgi-to-asgi.html">WSGI 到 ASGI 的适配</a>;下一篇:<a href="flask-thread-local-isolation.html">Thread Local 与请求隔离</a>。</p>'), ('与线程的对比', None), ('协作式的代价', None), ('threading.local 与 contextvars', None)],
    steps, [ENV_F + '。gevent 26.9.0、greenlet、gunicorn gevent worker', '没有验证:eventlet、Flask-SocketIO 在 gevent 下的行为、数据库驱动的 gevent 兼容(psycogreen 等)、monkey patch 的顺序问题与 SSL 递归错误、greenlet 栈内存开销'], 'Greenlet 与 Flask Context')
